/// Refetches only what failed. Called on reconnect (H6).
Future<void> retryFailedOverviewSections() async {
  final QuoteOverviewResponse? response = _lastOverviewResponse;
  final String? symbol = quoteInfo?.tradeSymbol;
  if (isClosed || response == null || symbol == null) return;
  if (_failedOverviewSections.isEmpty || selectedSection != MoGetQuoteSections.overview) return;
  final List<String> retry = _failedOverviewSections.toList();
  final List<bool> ok = await Future.wait(retry.map(
      (final String s) => _loadBatchSafely(symbol, <String>[s], response)));
  if (isClosed || !ok.contains(true)) return;
  _updateOverviewDataManager(response);
  _emitCurrentState(overviewDataManager);
}

final ValueNotifier<QuoteConnectivity> connectivity =
    ValueNotifier<QuoteConnectivity>(QuoteConnectivity.online);
StreamSubscription<bool>? _netSub;
StreamSubscription<Object?>? _socketSub;
bool _wasOffline = false;

void startConnectivityWatch() {
  if (!QuotePerfFlags.reconnectRefreshEnabled() || _netSub != null) return;
  _netSub = ConnectivityManager.instance.onConnectivityChanged.listen((final bool up) {
    if (isClosed) return;
    connectivity.value = connectivity.value.copyWith(interfaceUp: up);
    if (!up) { _wasOffline = true; return; }
    if (_wasOffline) { _wasOffline = false; unawaited(_refreshAfterReconnect()); }
  });
  _socketSub = BroadCastHelper.instance.socketStateStream.listen((final Object? s) {
    if (isClosed) return;
    final bool loggedIn = s == SocketState.loggedIn;
    connectivity.value = connectivity.value.copyWith(socketLoggedIn: loggedIn);
    if (loggedIn) unawaited(retryFailedOverviewSections()); // Wi-Fi without internet
  });
}

Future<void> _refreshAfterReconnect() async {
  await retryFailedOverviewSections(); // H5
  if (!isClosed && state is MoGetQuoteSectionError) await _loadSectionData(selectedSection);
}

@override
Future<void> close() {
  _debounceTimer?.cancel();
  _sectionDebounceTimer?.cancel();
  _netSub?.cancel();
  _socketSub?.cancel();
  connectivity.dispose();
  return super.close();
}

